/**
 * Personal API tokens. The raw secret never reaches this module — callers pass
 * the digest from `hashToken` and read it back the same way.
 */
import { and, count, desc, eq, gt, isNull, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { apiTokens, getDb } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { toApiToken } from "./_mappers";
import type { ApiTokenScope } from "@/types/api-token";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { ApiToken } from "@/types/api-token";

/** Usable tokens (not revoked, not expired) a single user may hold in one org. */
const MAX_USABLE_TOKENS = 5;

export interface InsertApiTokenRow {
  readonly orgId: OrgId;
  readonly userId: UserId;
  readonly name: string;
  readonly scope: ApiTokenScope;
  readonly prefix: string;
  readonly tokenHash: string;
  readonly expiresAt: IsoTimestamp;
  readonly createdAt: IsoTimestamp;
}

export async function countUsableApiTokens(
  orgId: OrgId,
  userId: UserId,
  now: IsoTimestamp,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(apiTokens)
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
        isNull(apiTokens.revokedAt),
        gt(apiTokens.expiresAt, now),
      ),
    )
    .get();
  return row?.value ?? 0;
}

/**
 * Inserts a token, rejecting when the user already holds the maximum number of
 * usable tokens. The count and the insert run before this function yields, so
 * a rejected call leaves the table unchanged.
 */
export async function insertApiToken(input: InsertApiTokenRow): Promise<ApiToken> {
  const usable = await countUsableApiTokens(
    input.orgId,
    input.userId,
    input.createdAt,
  );
  if (usable >= MAX_USABLE_TOKENS) {
    throw new Error(
      "A user may hold at most 5 usable API tokens per organization",
    );
  }

  const row = getDb()
    .insert(apiTokens)
    .values({
      id: newId(),
      orgId: input.orgId,
      userId: input.userId,
      name: input.name,
      scope: input.scope,
      prefix: input.prefix,
      tokenHash: input.tokenHash,
      expiresAt: input.expiresAt,
      lastUsedAt: null,
      revokedAt: null,
      createdAt: input.createdAt,
    })
    .returning()
    .get();

  return toApiToken(row);
}

/** Newest first. Revoked and expired rows are included. */
