import { emit, subscribe } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { createApiTokenSchema } from "@/schemas/api-token";
import { toIsoTimestamp } from "@/types/common";
import { actorEnvelope, orgResource, requireFound } from "./_support";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { TaskflowEventPayload, Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

const MS_PER_DAY = 24 * 60 * 60 * 1000;
const SECRET_BYTES = 32;
const PREFIX_LENGTH = 12;

export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);

  if (parsed.scope === "write") {
    assertCan(actor, "issue:create", orgResource(parsed.orgId));
  }

  const createdAtDate = new Date();
  const createdAt = toIsoTimestamp(createdAtDate);
  const expiresAt = toIsoTimestamp(
    new Date(createdAtDate.getTime() + parsed.expiresInDays * MS_PER_DAY),
  );
  const token = `tfk_${randomToken(SECRET_BYTES)}`;

  const apiToken = await apiTokenRepo.insertApiToken({
    orgId: parsed.orgId,
    userId: actor.userId,
    name: parsed.name,
    scope: parsed.scope,
    prefix: token.slice(0, PREFIX_LENGTH),
    tokenHash: hashToken(token),
    expiresAt,
    createdAt,
  });

  await emit("api_token.created", {
    ...actorEnvelope(actor),
    tokenId: apiToken.id,
    userId: apiToken.userId,
    name: apiToken.name,
    scope: apiToken.scope,
  });

  return { token, apiToken };
}

export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId?: UserId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  const targetUserId = userId ?? actor.userId;
  if (targetUserId !== actor.userId) {
    assertCan(actor, "member:remove", orgResource(orgId));
  }
  return apiTokenRepo.listApiTokensForUser(orgId, targetUserId);
}

export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);
  const existing = requireFound(
    await apiTokenRepo.findApiTokenById(orgId, tokenId),
    "ApiToken",
    tokenId,
  );
  if (existing.userId !== actor.userId) {
    assertCan(actor, "member:remove", orgResource(orgId));
  }
  if (existing.revokedAt !== null) return existing;

  const revokedAt = toIsoTimestamp(new Date());
  const revoked = await apiTokenRepo.markApiTokenRevoked(
    orgId,
    tokenId,
    revokedAt,
  );
  if (!revoked) return existing;

  await emit("api_token.revoked", {
    ...actorEnvelope(actor),
    tokenId: revoked.id,
    userId: revoked.userId,
  });

  return revoked;
}

/**
 * Resolves the actor a presented token stands for. Unknown, revoked, expired,
 * orphaned and deleted-org tokens resolve `null` and leave the row untouched.
 * A hit stamps `lastUsedAt`.
 */
export async function authenticateApiToken(token: string): Promise<Actor | null> {
  const now = new Date();
  const stored = await apiTokenRepo.findApiTokenByHash(hashToken(token));
  if (!stored) return null;
  if (stored.revokedAt !== null) return null;
  if (hasExpired(stored.expiresAt, now)) return null;

  const org = await orgRepo.findOrgById(stored.orgId);
  if (!org || org.archivedAt !== null) return null;

  const member = await memberRepo.findMember(stored.orgId, stored.userId);
  if (!member || member.status !== "active") return null;

  await apiTokenRepo.touchApiTokenLastUsed(
    stored.orgId,
    stored.id,
    toIsoTimestamp(now),
  );

  return {
    userId: stored.userId,
    orgId: stored.orgId,
    role: stored.scope === "read" ? "viewer" : member.role,
  };
}

/**
 * Member removal revokes every still-active token that user holds in the org,
 * expired ones included. Already-revoked rows keep their original timestamp
 * and are not audited again. Wired from `registerEventHandlers`.
 */
export function registerApiTokenListeners(): Unsubscribe {
  return subscribe("member.removed", (payload) =>
    revokeTokensForRemovedMember(payload),
  );
}

async function revokeTokensForRemovedMember(
  payload: TaskflowEventPayload<"member.removed">,
): Promise<void> {
  const revokedAt = toIsoTimestamp(new Date());
  const tokens = await apiTokenRepo.listUnrevokedApiTokens(
    payload.orgId,
    payload.userId,
  );

  for (const token of tokens) {
    const revoked = await apiTokenRepo.markApiTokenRevoked(
      payload.orgId,
      token.id,
      revokedAt,
    );
    if (!revoked) continue;

    await emit("api_token.revoked", {
      orgId: payload.orgId,
      actorId: payload.actorId,
      occurredAt: revokedAt,
      tokenId: revoked.id,
      userId: payload.userId,
    });
  }
}

function hasExpired(expiresAt: IsoTimestamp, now: Date): boolean {
  return Date.parse(expiresAt) <= now.getTime();
}

