  assertOrgScope(actor, orgId);
  const existing = requireFound(
    await apiTokenRepo.findApiTokenById(orgId, tokenId),
    "ApiToken",
    tokenId,
  );
  if (existing.userId !== actor.userId) {
    assertCan(actor, "member:remove", orgResource(orgId));
  }
  if (existing.revokedAt !== null) return existing;

  const revokedAt = toIsoTimestamp(new Date());
  const revoked = await apiTokenRepo.markApiTokenRevoked(
    orgId,
    tokenId,
    revokedAt,
  );
  if (!revoked) return existing;

  await emit("api_token.revoked", {
    ...actorEnvelope(actor),
    tokenId: revoked.id,
    userId: revoked.userId,
  });

  return revoked;
}

/**
 * Resolves the actor a presented token stands for. Unknown, revoked, expired,
 * orphaned and deleted-org tokens resolve `null` and leave the row untouched.
 * A hit stamps `lastUsedAt`.
 */
export async function authenticateApiToken(token: string): Promise<Actor | null> {
  const now = new Date();
  const stored = await apiTokenRepo.findApiTokenByHash(hashToken(token));
  if (!stored) return null;
  if (stored.revokedAt !== null) return null;
  if (hasExpired(stored.expiresAt, now)) return null;

  const org = await orgRepo.findOrgById(stored.orgId);
  if (!org || org.archivedAt !== null) return null;

  const member = await memberRepo.findMember(stored.orgId, stored.userId);
  if (!member || member.status !== "active") return null;

  await apiTokenRepo.touchApiTokenLastUsed(
    stored.orgId,
    stored.id,
    toIsoTimestamp(now),
  );

  return {
    userId: stored.userId,
    orgId: stored.orgId,
    role: stored.scope === "read" ? "viewer" : member.role,
  };
}

/**
 * Member removal revokes every still-active token that user holds in the org,
 * expired ones included. Already-revoked rows keep their original timestamp
 * and are not audited again. Wired from `registerEventHandlers`.
 */
export function registerApiTokenListeners(): Unsubscribe {
  return subscribe("member.removed", (payload) =>
    revokeTokensForRemovedMember(payload),
  );
}

async function revokeTokensForRemovedMember(
  payload: TaskflowEventPayload<"member.removed">,
): Promise<void> {
  const revokedAt = toIsoTimestamp(new Date());
  const tokens = await apiTokenRepo.listUnrevokedApiTokens(
    payload.orgId,
    payload.userId,
  );

  for (const token of tokens) {
    const revoked = await apiTokenRepo.markApiTokenRevoked(
      payload.orgId,
      token.id,
      revokedAt,
    );
    if (!revoked) continue;

    await emit("api_token.revoked", {
      orgId: payload.orgId,
      actorId: payload.actorId,
      occurredAt: revokedAt,
      tokenId: revoked.id,
      userId: payload.userId,
    });
  }
}

function hasExpired(expiresAt: IsoTimestamp, now: Date): boolean {
  return Date.parse(expiresAt) <= now.getTime();
}
