/**
 * Inserts a token, rejecting when the user already holds the maximum number of
 * usable tokens. The count and the insert share one transaction, so a rejected
 * call leaves the table unchanged.
 */
export async function insertApiToken(input: InsertApiTokenRow): Promise<ApiToken> {
  const row = getDb().transaction((tx) => {
    const usable = tx
      .select({ value: count() })
      .from(apiTokens)
      .where(usableWhere(input.orgId, input.userId, input.createdAt))
      .get();

    if ((usable?.value ?? 0) >= MAX_USABLE_TOKENS) {
      throw new Error(
        "A user may hold at most 5 usable API tokens per organization",
      );
    }

    return tx
      .insert(apiTokens)
      .values({
        id: newId(),
        orgId: input.orgId,
        userId: input.userId,
        name: input.name,
        scope: input.scope,
        prefix: input.prefix,
        tokenHash: input.tokenHash,
        expiresAt: input.expiresAt,
        lastUsedAt: null,
        revokedAt: null,
        createdAt: input.createdAt,
      })
      .returning()
      .get();
  });

  return toApiToken(row);
}

