export async function countUsableApiTokens(
  orgId: OrgId,
  userId: UserId,
  now: IsoTimestamp,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(apiTokens)
    .where(usableWhere(orgId, userId, now))
    .get();
  return row?.value ?? 0;
}

function usableWhere(orgId: OrgId, userId: UserId, now: IsoTimestamp) {
  return and(
    orgPredicate(apiTokens.orgId, orgId),
    eq(apiTokens.userId, userId),
    isNull(apiTokens.revokedAt),
    gt(apiTokens.expiresAt, now),
  );
}

