import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { ZodError } from "zod";
import { hashToken } from "@/lib/hash";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { getDb } from "@/server/db";
import { apiTokens } from "@/server/db/schema/api-tokens";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import {
  authenticateApiToken,
  createApiToken,
  listApiTokens,
  revokeApiToken,
} from "@/server/services/api-token-service";
import { registerEventHandlers, unregisterEventHandlers } from "@/server/services/event-registry";
import { removeMember } from "@/server/services/member-service";
import { NotFoundError } from "@/server/services/_support";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { OrgId } from "@/types/common";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
  tenant = await createTenant("tokens", "growth");
  other = await createTenant("tokens-other", "growth");
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

function input(
  orgId: OrgId,
  overrides: Partial<{ name: string; scope: "read" | "write"; expiresInDays: number }> = {},
) {
  return {
    orgId,
    name: "ci",
    scope: "read" as const,
    expiresInDays: 30,
    ...overrides,
  };
}

describe("api tokens", () => {
  it("creates, lists, authenticates and audits a read token", async () => {
    const before = Date.now();
    const created = await createApiToken(tenant.actors.viewer, input(tenant.org.id, { name: "  viewer token  " }));
    expect(created.token.startsWith("tfk_")).toBe(true);
    expect(created.apiToken.prefix).toBe(created.token.slice(0, 12));
    expect(created.apiToken.name).toBe("viewer token");
    expect(created.apiToken.lastUsedAt).toBeNull();
    expect(created.apiToken.revokedAt).toBeNull();
    expect(created.apiToken.userId).toBe(tenant.actors.viewer.userId);
    const expires = Date.parse(created.apiToken.expiresAt);
    expect(expires - Date.parse(created.apiToken.createdAt)).toBe(30 * 24 * 60 * 60 * 1000);

    const actor = await authenticateApiToken(created.token);
    expect(actor).toEqual({
      userId: tenant.actors.viewer.userId,
      orgId: tenant.org.id,
      role: "viewer",
    });
    const [listed] = await listApiTokens(tenant.actors.viewer, tenant.org.id);
    expect(listed?.lastUsedAt).not.toBeNull();
    expect(Date.parse(listed!.lastUsedAt!)).toBeGreaterThanOrEqual(before);

    const page = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["api_token.created"],
      limit: 25,
      cursor: null,
    });
    const row = page.items.find((item) => item.subjectId === created.apiToken.id);
    expect(row).toMatchObject({
      action: "api_token.created",
      subjectKind: "api_token",
      actorId: tenant.actors.viewer.userId,
    });
    const blob = JSON.stringify(row);
    expect(blob).not.toContain(created.token);
    expect(blob).not.toContain(hashToken(created.token));

    const stored = getDb().select().from(apiTokens).all();
    const mine = stored.find((row) => row.id === created.apiToken.id);
    expect(mine?.tokenHash).toBe(hashToken(created.token));
    expect(JSON.stringify(mine)).not.toContain(created.token);
  });

  it("rejects a viewer write token and invalid input without storing", async () => {
    const before = getDb().select().from(apiTokens).all().length;
    await expect(
      createApiToken(tenant.actors.viewer, input(tenant.org.id, { scope: "write" })),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      createApiToken(tenant.actors.viewer, input(tenant.org.id, { name: "   ", expiresInDays: 0 })),
    ).rejects.toBeInstanceOf(ZodError);
    await expect(
      createApiToken(tenant.actors.member, { ...input(tenant.org.id), expiresInDays: 1.5 }),
    ).rejects.toBeInstanceOf(ZodError);
    expect(getDb().select().from(apiTokens).all().length).toBe(before);
  });

  it("rejects another organization", async () => {
    await expect(
      createApiToken(tenant.actors.member, input(other.org.id, { scope: "write" })),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      listApiTokens(tenant.actors.owner, other.org.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("caps usable tokens at 5 and ignores revoked and expired", async () => {
    const user = tenant.actors.member;
    const made = [];
    for (let i = 0; i < 5; i += 1) {
      made.push(
        await createApiToken(user, input(tenant.org.id, { name: `t${i}`, scope: "write", expiresInDays: 1 })),
      );
    }
    const count = getDb().select().from(apiTokens).all().length;
    await expect(
      createApiToken(user, input(tenant.org.id, { name: "sixth", scope: "write" })),
    ).rejects.toThrow();
    expect(getDb().select().from(apiTokens).all().length).toBe(count);

    await revokeApiToken(user, tenant.org.id, made[0]!.apiToken.id);
    const again = await createApiToken(user, input(tenant.org.id, { name: "after revoke", scope: "write" }));
    expect(again.apiToken.name).toBe("after revoke");

    const expired = await createApiToken(tenant.actors.admin, input(tenant.org.id, { name: "exp", scope: "read", expiresInDays: 1 }));
    getDb()
      .update(apiTokens)
      .set({ expiresAt: toIsoTimestamp(new Date(Date.now() - 1000)) })
      .run();
    // that expired every token; recreate quota check for admin only by counting usable
    const adminTokens = await listApiTokens(tenant.actors.admin, tenant.org.id);
    expect(adminTokens.every((token) => Date.parse(token.expiresAt) <= Date.now() || token.revokedAt)).toBe(true);
    const fresh = await createApiToken(tenant.actors.admin, input(tenant.org.id, { name: "after expiry", scope: "read" }));
    expect(fresh.apiToken.name).toBe("after expiry");
    expect(await authenticateApiToken(expired.token)).toBeNull();
    const afterFail = await listApiTokens(tenant.actors.admin, tenant.org.id, tenant.actors.admin.userId);
    const expiredRow = afterFail.find((token) => token.id === expired.apiToken.id);
    expect(expiredRow?.lastUsedAt).toBeNull();
  });

  it("lists newest first and gates other users", async () => {
    const first = await createApiToken(tenant.actors.owner, input(tenant.org.id, { name: "older" }));
    await new Promise((resolve) => setTimeout(resolve, 5));
    const second = await createApiToken(tenant.actors.owner, input(tenant.org.id, { name: "newer" }));
    const listed = await listApiTokens(tenant.actors.owner, tenant.org.id);
    const names = listed.map((token) => token.name);
    expect(names.indexOf("newer")).toBeLessThan(names.indexOf("older"));
    expect(listed.some((token) => token.id === first.apiToken.id)).toBe(true);
    expect(listed.some((token) => token.id === second.apiToken.id)).toBe(true);

    await expect(
      listApiTokens(tenant.actors.member, tenant.org.id, tenant.actors.owner.userId),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    const asAdmin = await listApiTokens(tenant.actors.admin, tenant.org.id, tenant.actors.owner.userId);
    expect(asAdmin.some((token) => token.id === second.apiToken.id)).toBe(true);
  });

  it("revokes once and denies revoking someone else's token", async () => {
    const created = await createApiToken(tenant.actors.owner, input(tenant.org.id, { name: "revoke me", scope: "write" }));
    await expect(
      revokeApiToken(tenant.actors.member, tenant.org.id, created.apiToken.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    expect((await authenticateApiToken(created.token))?.role).toBe("owner");

    const revoked = await revokeApiToken(tenant.actors.admin, tenant.org.id, created.apiToken.id);
    expect(revoked.revokedAt).not.toBeNull();
    const again = await revokeApiToken(tenant.actors.owner, tenant.org.id, created.apiToken.id);
    expect(again.revokedAt).toBe(revoked.revokedAt);
    expect(await authenticateApiToken(created.token)).toBeNull();

    const page = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["api_token.revoked"],
      subjectKind: "api_token",
      limit: 100,
      cursor: null,
    });
    const rows = page.items.filter((item) => item.subjectId === created.apiToken.id);
    expect(rows).toHaveLength(1);
    expect(rows[0]?.actorId).toBe(tenant.actors.admin.userId);
    expect(JSON.stringify(rows[0])).not.toContain(created.token);
    expect(JSON.stringify(rows[0])).not.toContain(hashToken(created.token));

    await expect(
      revokeApiToken(tenant.actors.owner, tenant.org.id, "missing-token"),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("stops at exactly expiresAt and follows role changes", async () => {
    const created = await createApiToken(tenant.actors.admin, input(tenant.org.id, { name: "clock", scope: "write", expiresInDays: 2 }));
    getDb()
      .update(apiTokens)
      .set({ expiresAt: toIsoTimestamp(new Date()) })
      .where((await import("drizzle-orm")).eq(apiTokens.id, created.apiToken.id))
      .run();
    expect(await authenticateApiToken(created.token)).toBeNull();

    const live = await createApiToken(tenant.actors.admin, input(tenant.org.id, { name: "demote", scope: "write" }));
    const member = await memberRepo.findMember(tenant.org.id, tenant.actors.admin.userId);
    await memberRepo.updateMemberRole(tenant.org.id, member!.id, "member");
    expect(await authenticateApiToken(live.token)).toMatchObject({ role: "member" });
    await memberRepo.updateMemberRole(tenant.org.id, member!.id, "admin");
  });

  it("revokes a removed member's tokens in that org only", async () => {
    const home = await createApiToken(tenant.actors.viewer, input(tenant.org.id, { name: "home" }));
    const away = await createApiToken(
      { ...tenant.actors.viewer, orgId: other.org.id },
      input(other.org.id, { name: "away" }),
    );
    // viewer is not a member of other; create will tenant-scope fail. Seed membership.
  });
});

