input.new_string:
  it("revokes a removed member's tokens in that org only", async () => {
    await memberRepo.insertMember(other.org.id, tenant.userIds.viewer, "member", null);
    const home = await createApiToken(
      tenant.actors.viewer,
      input(tenant.org.id, { name: "home" }),
    );
    const awayActor = {
      userId: tenant.userIds.viewer,
      orgId: other.org.id,
      role: "member" as const,
    };
    const away = await createApiToken(awayActor, input(other.org.id, { name: "away" }));
    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    await removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member!.id,
    });

    expect(await authenticateApiToken(home.token)).toBeNull();
    const homeRow = (await listApiTokens(tenant.actors.owner, tenant.org.id, tenant.userIds.viewer)).find(
      (token) => token.id === home.apiToken.id,
    );
    expect(homeRow?.revokedAt).not.toBeNull();
    const awayRow = (
      await listApiTokens(awayActor, other.org.id, tenant.userIds.viewer)
    ).find((token) => token.id === away.apiToken.id);
    expect(awayRow?.revokedAt).toBeNull();
    expect(await authenticateApiToken(away.token)).toMatchObject({
      role: "viewer",
      orgId: other.org.id,
    });

    const page = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["api_token.revoked"],
      limit: 100,
      cursor: null,
    });
    const audited = page.items.filter((item) => item.subjectId === home.apiToken.id);
    expect(audited).toHaveLength(1);
    expect(audited[0]?.actorId).toBe(tenant.actors.owner.userId);
    expect(JSON.stringify(audited[0])).not.toContain(home.token);
  });

  it("refuses a token once its organization is deleted", async () => {
    const created = await createApiToken(
      other.actors.owner,
      input(other.org.id, { name: "doomed", scope: "write" }),
    );
    expect(await authenticateApiToken(created.token)).toMatchObject({ role: "owner" });
    await orgRepo.archiveOrg(other.org.id);
    expect(await authenticateApiToken(created.token)).toBeNull();
    const row = (await listApiTokens(other.actors.owner, other.org.id)).find(
      (token) => token.id === created.apiToken.id,
    );
    expect(row?.lastUsedAt).not.toBeNull();
    expect(row?.revokedAt).toBeNull();
  });
});

